port this code from Object Pascal to python:
```pascal
function closest_to_zero(nums: array of integer): integer;
var
  smallest_distance, largest_closest_number, distance, num: integer;
begin
  smallest_distance := MaxInt;
  largest_closest_number := -MaxInt;

  for num in nums do
  begin
    distance := Abs(num);

    if distance < smallest_distance then
    begin
      smallest_distance := distance;
      largest_closest_number := num;
    end
    else if distance = smallest_distance then
    begin
      if num > largest_closest_number then
        largest_closest_number := num;
    end;
  end;

  Result := largest_closest_number;
end;
```

